            con = DriverManager.getConnection(url, userid, passwd);
            list = dao.list(con);  // con을 DAO에 전달
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            try {
                if (con != null) con.close();  // con은 여기서 닫음
            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
        return list;
    }
}
