// com/exam/security/SecurityConfig.java
@Configuration
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {

        // csrf 비활성화
        http.csrf(AbstractHttpConfigurer::disable);

        // 인증/비인증 요청 설정
        http.authorizeHttpRequests(authorize ->
                authorize
                    .requestMatchers("/", "/home", "/signup", "/login").permitAll() // 인증 없이 접근 가능
                    .anyRequest().authenticated()  // 나머지는 인증 필요
        );

        // 로그인 설정
        http.formLogin(form ->
            form
                .loginPage("/login")              // 로그인 화면 URL
                .loginProcessingUrl("/auth")      // form action 경로
                .usernameParameter("userid")      // input name="userid"
                .passwordParameter("password")   // input name="password"
                .defaultSuccessUrl("/home", true) // 로그인 성공 시 이동
                .failureUrl("/login?error=true")  // 로그인 실패 시 이동
                .permitAll()
        );

        // 로그아웃 설정
        http.logout(logout ->
                logout
                    .logoutUrl("/logout")
                    .logoutSuccessUrl("/home")
                    .invalidateHttpSession(true)   // 세션 무효화
                    .deleteCookies("JSESSIONID")   // 쿠키 삭제
                    .permitAll()
        );

        return http.build();
    }

    // 비밀번호 암호화 Bean
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
